"""Command-line framework: command registry, argument reading, context, I/O."""
import os
import re
import sys
from datetime import date

from ..errors import NotFoundError, TallybookError

PROG = "tallybook"
VERSION = "1.0.0"


class UsageError(Exception):
    """The command line itself is wrong (exit status 2)."""

    def __init__(self, message):
        super().__init__(message)
        self.message = message


class CliError(Exception):
    """The program refused (exit status 1): one line on stderr, nothing on stdout."""

    def __init__(self, message, extra=()):
        super().__init__(message)
        self.message = message
        self.extra = list(extra)


# ---------------------------------------------------------------- registry
REGISTRY = {}  # words tuple -> Command


class Command:
    def __init__(self, words, summary, args, options, flags, repeat, required, aliases, handler):
        self.words = tuple(words)
        self.summary = summary
        self.options = dict(options)  # "--name" -> METAVAR
        self.flags = tuple(flags)
        self.repeat = set(repeat)
        self.required = set(required)
        self.aliases = dict(aliases)  # "-p" -> "--posting"
        self.handler = handler
        self.positionals = []  # (name, kind) kind: req | opt | many | any
        for tok in args.split():
            if tok.startswith("[") and tok.endswith("...]"):
                self.positionals.append((tok[1:-4], "any"))
            elif tok.startswith("[") and tok.endswith("]"):
                self.positionals.append((tok[1:-1], "opt"))
            elif tok.endswith("..."):
                self.positionals.append((tok[:-3], "many"))
            else:
                self.positionals.append((tok, "req"))

    @property
    def name(self):
        return " ".join(self.words)

    def usage(self):
        parts = ["usage: %s %s" % (PROG, self.name)]
        for name, kind in self.positionals:
            parts.append({"req": name, "opt": "[%s]" % name, "many": name + " ...", "any": "[%s ...]" % name}[kind])
        for opt, meta in self.options.items():
            rev = [a for a, full in self.aliases.items() if full == opt]
            shown = "%s %s" % (opt, meta)
            if rev:
                shown = "%s|%s %s" % (rev[0], opt, meta)
            if opt in self.required:
                parts.append(shown)
            else:
                parts.append("[%s]%s" % (shown, " ..." if opt in self.repeat else ""))
        for fl in self.flags:
            parts.append("[%s]" % fl)
        return " ".join(parts)


def command(words, summary, args="", options=None, flags=(), repeat=(), required=(), aliases=None):
    """Register a handler `fn(ctx, a)` for the command `words` (a string like "account add")."""

    def deco(fn):
        cmd = Command(words.split(), summary, args, options or {}, flags, repeat, required, aliases or {}, fn)
        REGISTRY[cmd.words] = cmd
        return fn

    return deco


class Parsed:
    def __init__(self, args, opts, flags):
        self.args = args
        self._opts = opts
        self._flags = flags

    def get(self, name, default=None):
        v = self._opts.get(name)
        if v is None:
            return default
        return v[-1]

    def all(self, name):
        return list(self._opts.get(name, []))

    def flag(self, name):
        return name in self._flags


def parse_args(cmd, argv):
    """Read `argv` (the words after the command words) against `cmd`."""
    opts, flags, plain = {}, set(), []
    i, n = 0, len(argv)
    while i < n:
        a = argv[i]
        i += 1
        if a == "--":
            plain.extend(argv[i:])
            break
        if a.startswith("--") and len(a) > 2:
            name, eq, val = a.partition("=")
            if name in cmd.options:
                if not eq:
                    if i >= n:
                        raise UsageError("option %s needs a value" % name)
                    val = argv[i]
                    i += 1
                if name in opts and name not in cmd.repeat:
                    raise UsageError("option %s given twice" % name)
                opts.setdefault(name, []).append(val)
            elif name in cmd.flags:
                if eq:
                    raise UsageError("option %s takes no value" % name)
                if name in flags:
                    raise UsageError("option %s given twice" % name)
                flags.add(name)
            else:
                raise UsageError("unknown option %s" % name)
        elif a in cmd.aliases:
            name = cmd.aliases[a]
            if i >= n:
                raise UsageError("option %s needs a value" % a)
            val = argv[i]
            i += 1
            if name in opts and name not in cmd.repeat:
                raise UsageError("option %s given twice" % name)
            opts.setdefault(name, []).append(val)
        else:
            plain.append(a)
    for opt in cmd.required:
        if opt not in opts:
            raise UsageError("missing required option %s" % opt)
    pos = []
    k = 0
    for name, kind in cmd.positionals:
        if kind == "req":
            if k >= len(plain):
                raise UsageError("missing argument %s" % name)
            pos.append(plain[k])
            k += 1
        elif kind == "opt":
            if k < len(plain):
                pos.append(plain[k])
                k += 1
            else:
                pos.append(None)
        else:
            rest = plain[k:]
            if kind == "many" and not rest:
                raise UsageError("missing argument %s" % name)
            pos.append(rest)
            k = len(plain)
    if k < len(plain):
        raise UsageError("unexpected argument '%s'" % plain[k])
    return Parsed(pos, opts, flags)


def wants_help(cmd, argv):
    """True when -h/--help stands as an option of its own (not as an option's value)."""
    i, n = 0, len(argv)
    while i < n:
        a = argv[i]
        i += 1
        if a == "--":
            return False
        if a in ("-h", "--help"):
            return True
        if a.startswith("--") and "=" not in a and a in cmd.options:
            i += 1
        elif a in cmd.aliases:
            i += 1
    return False


# ---------------------------------------------------------------- context
_INT_RE = re.compile(r"-?[0-9]{1,18}")


def parse_int(text, what="number", negative=False):
    """A whole number in decimal digits, at most 18 of them."""
    if not isinstance(text, str) or not _INT_RE.fullmatch(text) or (text[0] == "-" and not negative):
        raise CliError("invalid %s '%s'" % (what, text))
    return int(text)


class Context:
    def __init__(self, db=None, today=None):
        self._db = db
        self._today = today
        self.out_parts = []

    # --- output
    def write(self, text):
        self.out_parts.append(text)

    def line(self, text=""):
        self.out_parts.append(text + "\n")

    def json(self, value):
        from ..export import to_json

        self.out_parts.append(to_json(value))

    @property
    def output(self):
        return "".join(self.out_parts)

    # --- configuration
    @property
    def db_path(self):
        if self._db is not None:
            path = self._db
        else:
            env = os.environ.get("TALLYBOOK_DB")
            path = env if env else "tallybook.db"
        if "\0" in path:
            raise CliError("invalid file name '%s': it contains a NUL character" % path.replace("\0", " "))
        return path

    @property
    def today(self):
        return self._today if self._today is not None else date.today()

    # --- book
    def open_store(self, gate=True, create=False):
        from ..storage import LATEST_VERSION, Store

        path = self.db_path
        try:
            store = Store.open(path, create=create)
        except NotFoundError:
            if not create and not os.path.exists(path):
                raise CliError("no such database: %s (run `tallybook init`)" % path) from None
            raise
        if gate:
            version = store.version
            if version < LATEST_VERSION:
                store.close()
                raise CliError("database is at version %d, run `tallybook db migrate`" % version)
        return store

    # --- input files
    @staticmethod
    def read_text(file):
        """Read a UTF-8 file ('-' is standard input); returns (text, label)."""
        if file == "-":
            label = "standard input"
            try:
                src = getattr(sys.stdin, "buffer", None)
                raw = src.read() if src is not None else sys.stdin.read()
            except OSError as e:
                raise CliError("cannot read %s: %s" % (label, e.strerror or e)) from None
        else:
            label = file
            try:
                with open(file, "rb") as fh:
                    raw = fh.read()
            except (OSError, ValueError) as e:
                raise CliError("cannot read %s: %s" % (file.replace("\x00", "?"), getattr(e, "strerror", None) or e)) from None
        if isinstance(raw, bytes):
            try:
                text = raw.decode("utf-8")
            except UnicodeDecodeError:
                raise CliError("%s is not valid UTF-8 text" % label) from None
        else:
            text = raw
        return text, label


def error_message(exc):
    if isinstance(exc, TallybookError):
        return exc.message
    return str(exc)
"""The `tallybook` command line: `main(argv=None) -> int`."""
import os
import sys

from ..dates import DateError, parse_date
from ..errors import TallybookError
from .framework import (
    PROG,
    REGISTRY,
    VERSION,
    CliError,
    Context,
    UsageError,
    parse_args,
    wants_help,
)

TRY = "Try 'tallybook --help'."


def _load_commands():
    from . import commands_book, commands_calc  # noqa: F401  (register on import)


def _top_help():
    lines = ["usage: tallybook [--db FILE] [--today DATE] COMMAND [WORD] [ARGUMENTS and --options]", ""]
    lines += [
        "global options:",
        "  --db FILE      the book file (default: $TALLYBOOK_DB, else tallybook.db)",
        "  --today DATE   what 'today' is (default: the real date)",
        "  --version      print the version and stop",
        "  -h, --help     print this help and stop",
        "",
        "commands:",
    ]
    for words in sorted(REGISTRY, key=lambda w: (w[0] == "calc", w)):
        cmd = REGISTRY[words]
        lines.append("  %-28s %s" % (cmd.name, cmd.summary))
    return "\n".join(lines) + "\n"


def _group_help(prefix):
    n = len(prefix)
    names = sorted({w[n] for w in REGISTRY if len(w) > n and w[:n] == prefix})
    lines = ["usage: tallybook %s WORD [ARGUMENTS and --options]" % " ".join(prefix), "", "words:"]
    for name in names:
        full = prefix + (name,)
        cmd = REGISTRY.get(full)
        lines.append("  %-14s %s" % (name, cmd.summary if cmd else "..."))
    return "\n".join(lines) + "\n"


def _plain_help(argv):
    for a in argv:
        if a == "--":
            return False
        if a in ("-h", "--help"):
            return True
    return False


def _is_group(prefix):
    n = len(prefix)
    return any(len(w) > n and w[:n] == prefix for w in REGISTRY)


def _emit(text):
    out = sys.stdout
    buf = getattr(out, "buffer", None)
    if buf is not None:
        out.flush()
        buf.write(text.encode("utf-8"))
        buf.flush()
    else:
        out.write(text)
        out.flush()


def _quiet_stdout():
    try:
        fd = os.open(os.devnull, os.O_WRONLY)
        os.dup2(fd, sys.stdout.fileno())
    except Exception:
        pass


def _err(text):
    try:
        sys.stderr.write(text)
        sys.stderr.flush()
    except Exception:
        pass


def _finish(status, text, err_text=""):
    """Write the buffered output; map broken pipes and unwritable stdout."""
    if err_text:
        _err(err_text)
    if text:
        try:
            _emit(text)
        except BrokenPipeError:
            _quiet_stdout()
            return 0
        except OSError as e:
            _quiet_stdout()
            _err("tallybook: cannot write output: %s\n" % (e.strerror or e))
            return 1
        except UnicodeError:
            _err("tallybook: cannot write output: not valid UTF-8 text\n")
            return 1
    return status


def _usage_failure(msg):
    return _finish(2, "", "tallybook: %s\n%s\n" % (msg, TRY))


def main(argv=None):
    if argv is None:
        argv = sys.argv[1:]
    argv = list(argv)
    try:
        return _main(argv)
    except RecursionError:
        return _finish(1, "", "tallybook: input is nested too deeply\n")
    except KeyboardInterrupt:
        return 130
    except BrokenPipeError:
        _quiet_stdout()
        return 0
    except Exception as e:  # last resort: never a traceback
        return _finish(1, "", "tallybook: unexpected error: %s\n" % (str(e).replace("\n", " ") or type(e).__name__))


def _main(argv):
    _load_commands()
    for a in argv:
        try:
            a.encode("utf-8")
        except UnicodeEncodeError:
            return _finish(1, "", "tallybook: argument is not valid UTF-8 text\n")
    db = today = None
    seen = set()
    i = 0
    try:
        while i < len(argv):
            a = argv[i]
            name, eq, val = a.partition("=") if a.startswith("--") else (a, "", "")
            if name in ("--db", "--today"):
                if name in seen:
                    raise UsageError("option %s given twice" % name)
                seen.add(name)
                if eq:
                    i += 1
                else:
                    if i + 1 >= len(argv):
                        raise UsageError("option %s needs a value" % name)
                    val = argv[i + 1]
                    i += 2
                if name == "--db":
                    db = val
                else:
                    try:
                        today = parse_date(val)
                    except DateError as e:
                        return _finish(1, "", "tallybook: %s\n" % e.message)
            elif name == "--version" and not eq:
                return _finish(0, "tallybook %s\n" % VERSION)
            elif a in ("-h", "--help"):
                return _finish(0, _top_help())
            else:
                break
        rest = argv[i:]
        if not rest:
            raise UsageError("no command")
        words, k = [], 0
        node_prefix = ()
        while True:
            if k >= len(rest) or rest[k].startswith("-") and rest[k] not in ("-",):
                # ran out of words (or hit an option) while a group still needs a word
                if not node_prefix:
                    raise UsageError("unknown option %s" % rest[k])
                if _is_group(node_prefix):
                    if k < len(rest) and _plain_help(rest[k:]):
                        return _finish(0, _group_help(node_prefix))
                    raise UsageError("%s needs a word" % " ".join(node_prefix))
                break
            word = rest[k]
            cand = node_prefix + (word,)
            if cand in REGISTRY or _is_group(cand):
                node_prefix = cand
                k += 1
                if cand in REGISTRY:
                    break
                continue
            if not node_prefix:
                raise UsageError("unknown command '%s'" % word)
            raise UsageError("unknown word '%s' for %s" % (word, " ".join(node_prefix)))
        cmdargs = rest[k:]
        if node_prefix in REGISTRY:
            cmd = REGISTRY[node_prefix]
            if wants_help(cmd, cmdargs):
                return _finish(0, cmd.usage() + "\n")
            parsed = parse_args(cmd, cmdargs)
            ctx = Context(db=db, today=today)
            try:
                status = cmd.handler(ctx, parsed) or 0
            except CliError as e:
                return _finish(1, "", "".join("tallybook: %s\n" % e.message if j == 0 else l + "\n"
                                               for j, l in enumerate([e.message] + e.extra)))
            except TallybookError as e:
                return _finish(1, "", "tallybook: %s\n" % e.message)
            return _finish(status, ctx.output)
        # a group word with --help
        if _plain_help(cmdargs):
            return _finish(0, _group_help(node_prefix))
        raise UsageError("%s needs a word" % " ".join(node_prefix))
    except UsageError as e:
        return _usage_failure(e.message)
"""Shared helpers of the book commands: posting arguments, listings, money text."""
import re

from ..accounts import valid_path
from ..dates import Period, format_date, parse_date
from ..errors import TallybookError
from ..export import money_to_dict, render_table, transaction_to_dict
from ..model import Posting, Transaction
from ..money import Money
from .framework import CliError, parse_int

_BLANKS = " \t"
_SPLIT = re.compile(r"[ \t]+")
POSTING_OPTION = {"--posting": "POSTING"}
POSTING_ALIASES = {"-p": "--posting"}
TX_FIELD_OPTIONS = {"--narration": "TEXT", "--flag": "F", "--tag": "TAG"}
PERIOD_KINDS = ("month", "quarter", "year")


def parse_posting(text):
    """Read one posting argument: ACCOUNT, or ACCOUNT AMOUNT CUR, then an optional `; note`."""
    head, _, note = text.partition(";")
    parts = _SPLIT.split(head.strip(_BLANKS)) if head.strip(_BLANKS) else []
    if len(parts) not in (1, 3):
        raise CliError("invalid posting '%s': expected ACCOUNT or ACCOUNT AMOUNT CURRENCY" % text)
    if not valid_path(parts[0]):
        raise CliError("invalid posting '%s': invalid account path '%s'" % (text, parts[0]))
    amount = None
    if len(parts) == 3:
        try:
            amount = Money.of(parts[1], parts[2])
        except TallybookError as e:
            raise CliError("invalid posting '%s': %s" % (text, e.message)) from None
    return Posting(parts[0], amount, note.strip(_BLANKS))


def date_option(a, name, default):
    value = a.get(name)
    return default if value is None else parse_date(value)


def optional_date(a, name):
    value = a.get(name)
    return None if value is None else parse_date(value)


def whole_number(a, name, what):
    value = a.get(name)
    return None if value is None else parse_int(value, what)


def build_transaction(a, on, payee):
    """The transaction described by --narration/--flag/--tag/--posting of a command."""
    postings = [parse_posting(p) for p in a.all("--posting")]
    return Transaction(
        on, payee, a.get("--narration", ""), postings, tuple(a.all("--tag")), a.get("--flag", "*"), None
    )


def month_of(today):
    return Period.parse("%04d-%02d" % (today.year, today.month))


def money_text(money):
    return "%s %s" % (money.amount_str(), money.currency)


def money_list_text(monies):
    return ", ".join(money_text(m) for m in monies)


def need_kind(kind):
    if kind not in PERIOD_KINDS:
        raise CliError("invalid period kind '%s': expected month, quarter or year" % kind)
    return kind


def tags_text(tx):
    return " ".join("#" + t for t in sorted(set(tx.tags)))


def print_transactions(ctx, txs, as_json):
    """The `tx list` output: a table, or a JSON list; an empty list prints nothing (`[]` in JSON)."""
    txs = list(txs)
    if as_json:
        ctx.json([transaction_to_dict(tx) for tx in txs])
    elif txs:
        rows = [[tx.id, format_date(tx.date), tx.flag, tx.payee, tx.narration, tags_text(tx)] for tx in txs]
        ctx.write(render_table(["Id", "Date", "Flag", "Payee", "Narration", "Tags"], rows, "rlllll"))


def print_table(ctx, headers, rows, align):
    if rows:
        ctx.write(render_table(headers, rows, align))


def account_dict(acct):
    return {
        "path": acct.path,
        "type": acct.type,
        "currency": acct.currency,
        "opened": None if acct.opened is None else format_date(acct.opened),
        "closed": None if acct.closed is None else format_date(acct.closed),
        "note": acct.note,
    }


def posting_dict(p):
    return {"account": p.account, "amount": money_to_dict(p.amount), "note": p.note}
import sys

from tallybook.cli.main import main

if __name__ == "__main__":
    sys.exit(main())
