"""`calc` commands: the library on the command line, without a book."""
import re
from datetime import date

from .. import reports
from ..accounts import account_type, parent_path, path_matches
from ..budgets import Budget, budget_status
from ..csvimport import import_csv
from ..currency import RateTable
from ..dates import Period, add_months, format_date, parse_date, periods
from ..export import render_table, to_json, transaction_to_dict
from ..journal import Journal, JournalError, format_journal, parse_journal
from ..model import Transaction
from ..money import Money
from ..query import parse_query, select
from ..recurring import Recurring, occurrences, parse_schedule
from ..rules import parse_rules
from .framework import CliError, UsageError, command, parse_int

_WEEKDAYS = ("Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday")
_RATIO = re.compile(r"(-?[0-9]{1,18})(?:/(-?[0-9]{1,18}))?")
_MAX_PERIODS = 5000
_MAX_SCHEDULE_DAYS = 40000
_LONGEST = {"week": 7, "month": 31, "quarter": 92, "year": 366}
_REPORT_KINDS = ("trial-balance", "balance-sheet", "income-statement", "cashflow", "register")
_RATE_DAY = date(2000, 1, 1)


# ------------------------------------------------------------------ helpers
def _read(ctx, file):
    return ctx.read_text(file)


def _load_journal(ctx, file):
    """Read and parse a journal file; writing mistakes read `FILE: line N: ...`."""
    text, label = _read(ctx, file)
    try:
        return parse_journal(text), label
    except JournalError as e:
        raise CliError("%s: %s" % (label, e.message)) from None


def _load_ledger(ctx, file):
    journal, _ = _load_journal(ctx, file)
    return journal.to_ledger()


def _keyed(key, value):
    return ("%s: %s" % (key, value)).rstrip()


def _tx_table(txs):
    rows = []
    for tx in txs:
        tags = " ".join("#" + t for t in sorted(set(tx.tags)))
        rows.append([tx.id, format_date(tx.date), tx.flag, tx.payee, tx.narration, tags])
    return render_table(["Id", "Date", "Flag", "Payee", "Narration", "Tags"], rows, "rlllll")


def _budget_table(lines):
    rows = [
        [
            ln.pattern,
            ln.period_kind,
            str(ln.budget),
            str(ln.actual),
            str(ln.remaining),
            "%s%%" % ln.percent,
            "over" if ln.over else "",
        ]
        for ln in lines
    ]
    return render_table(
        ["Pattern", "Per", "Budget", "Actual", "Remaining", "Percent", "Over"], rows, "llrrrrl"
    )


def _month_of(day):
    return Period.parse("%04d-%02d" % (day.year, day.month))


# -------------------------------------------------------------------- money
@command("calc money parse", "read an amount: minor units and currency", args="MONEY")
def money_parse(ctx, a):
    m = Money.parse(a.args[0])
    ctx.line("%d %s" % (m.minor, m.currency))


@command("calc money format", "write minor units as an amount", args="MINOR CUR")
def money_format(ctx, a):
    minor = parse_int(a.args[0], "amount", negative=True)
    ctx.line(str(Money(minor, a.args[1])))


@command("calc money add", "add two amounts", args="A B")
def money_add(ctx, a):
    ctx.line(str(Money.parse(a.args[0]) + Money.parse(a.args[1])))


@command("calc money sub", "subtract two amounts", args="A B")
def money_sub(ctx, a):
    ctx.line(str(Money.parse(a.args[0]) - Money.parse(a.args[1])))


@command("calc money scale", "multiply an amount by N or N/D", args="MONEY RATIO")
def money_scale(ctx, a):
    m = Money.parse(a.args[0])
    found = _RATIO.fullmatch(a.args[1])
    if not found:
        raise CliError("invalid ratio '%s': expected N or N/D" % a.args[1])
    num = int(found.group(1))
    den = int(found.group(2)) if found.group(2) is not None else 1
    ctx.line(str(m.scale(num, den)))


@command("calc money allocate", "split an amount by weights", args="MONEY W...")
def money_allocate(ctx, a):
    m = Money.parse(a.args[0])
    weights = [parse_int(w, "weight") for w in a.args[1]]
    for part in m.allocate(weights):
        ctx.line(str(part))


@command("calc money convert", "convert an amount at one rate", args="MONEY TO RATE")
def money_convert(ctx, a):
    m = Money.parse(a.args[0])
    if a.args[1] == m.currency:
        raise CliError("cannot convert %s to itself" % m.currency)
    table = RateTable()
    table.set(m.currency, a.args[1], a.args[2], _RATE_DAY)
    ctx.line(str(table.convert(m, a.args[1], _RATE_DAY)))


# -------------------------------------------------------------------- dates
@command("calc date parse", "a date and its weekday", args="DATE")
def date_parse(ctx, a):
    d = parse_date(a.args[0])
    ctx.line("%s %s" % (format_date(d), _WEEKDAYS[d.weekday()]))


@command("calc date add-months", "move a date by whole months", args="DATE N")
def date_add_months(ctx, a):
    d = parse_date(a.args[0])
    n = parse_int(a.args[1], "number of months", negative=True)
    ctx.line(format_date(add_months(d, n)))


@command("calc date period", "the facts about one period", args="PERIOD")
def date_period(ctx, a):
    p = Period.parse(a.args[0])
    following = p.next()
    ctx.line("start: %s" % format_date(p.start))
    ctx.line("end: %s" % format_date(p.end))
    ctx.line("days: %d" % p.days)
    ctx.line("label: %s" % p.label)
    ctx.line("next: %s" % following.label)


@command("calc date periods", "the periods covering two dates", args="START END STEP")
def date_periods(ctx, a):
    start = parse_date(a.args[0])
    end = parse_date(a.args[1])
    step = a.args[2]
    longest = _LONGEST.get(step)
    if longest is not None and end >= start and (end - start).days + 1 > _MAX_PERIODS * longest:
        raise CliError("more than %d periods" % _MAX_PERIODS)
    found = periods(start, end, step)
    if len(found) > _MAX_PERIODS:
        raise CliError("more than %d periods" % _MAX_PERIODS)
    for p in found:
        ctx.line(p.label)


@command(
    "calc schedule",
    "the dates of a recurring schedule inside a window",
    args="SCHEDULE",
    options={
        "--from": "DATE",
        "--to": "DATE",
        "--start": "DATE",
        "--end": "DATE",
        "--count": "N",
    },
    required=("--from", "--to"),
)
def schedule_dates(ctx, a):
    schedule = parse_schedule(a.args[0])
    first = parse_date(a.get("--from"))
    last = parse_date(a.get("--to"))
    start = parse_date(a.get("--start")) if a.get("--start") is not None else first
    end = parse_date(a.get("--end")) if a.get("--end") is not None else None
    count = parse_int(a.get("--count"), "count") if a.get("--count") is not None else None
    if (last - min(first, start)).days > _MAX_SCHEDULE_DAYS:
        raise CliError("the window is longer than %d days" % _MAX_SCHEDULE_DAYS)
    rec = Recurring("calc", schedule, Transaction(start, "calc"), start, end, count)
    for day in occurrences(rec, first, last):
        ctx.line(format_date(day))


# ---------------------------------------------------- accounts, rates, rules
@command("calc account check", "read an account path", args="PATH")
def account_check(ctx, a):
    path = a.args[0]
    kind = account_type(path)
    parent = parent_path(path)
    ctx.line("path: %s" % path)
    ctx.line("type: %s" % kind)
    ctx.line("parent: %s" % ("none" if parent is None else parent))


@command("calc account match", "does an account pattern match a path", args="PATTERN PATH")
def account_match(ctx, a):
    ctx.line("yes" if path_matches(a.args[0], a.args[1]) else "no")


@command(
    "calc rules",
    "which rule of a rules file wins",
    args="FILE",
    options={"--payee": "TEXT", "--narration": "TEXT", "--amount": "MONEY", "--date": "DATE"},
)
def rules_winner(ctx, a):
    text, _ = _read(ctx, a.args[0])
    rules = parse_rules(text)
    fields = {}
    if a.get("--payee") is not None:
        fields["payee"] = a.get("--payee")
    if a.get("--narration") is not None:
        fields["narration"] = a.get("--narration")
    if a.get("--amount") is not None:
        fields["amount"] = Money.parse(a.get("--amount"))
    if a.get("--date") is not None:
        fields["date"] = parse_date(a.get("--date"))
    rule = rules.match(fields)
    if rule is None:
